  Lemma umap_xfer_rh : forall (lv1 lv' X : list (Z * Z)) (bl bc bl' bc' : Z) (rehashed : bool),
    NoDup (map fst lv1) -> NoDup (map fst lv') -> 0 <= bc ->
    Permutation lv1 ((if bc =? 0 then [] else [(bl, 8 * bc)]) ++ X) ->
    (rehashed = false -> bl' = bl /\ bc' = bc) -> (rehashed = true -> bc' <> 0) ->
    lapply lv1 (if rehashed then LAdd bl' (8 * bc') :: (if bc =? 0 then [] else [LDel bl]) else []) lv' ->
    Permutation lv' ((if bc' =? 0 then [] else [(bl', 8 * bc')]) ++ X).
