  Lemma pm_h5 : forall (w : pmw MI ST) c0 K (fx : FPState) A M model c R (key w1 w2 w3 : Z),
    PMS w c0 K -> frm_zero (@fp_csr fx) -> fconsts fx ->
    PMX w A M model c -> c_tr c = [] -> pm_bud (w_n w) c ->
    PmLoopU1.nodes c + 2 <= c_widx c + 3 -> PmLoopU1.macct c -> 2 * Zlen (t3c (c_m2 c)) + 2 <= c_widx c ->
    oregs w R -> getr R 15%bv = Z_to_bv 64 w3 ->
    cell8 SEGS M (w_sp w + 16) w1 -> cell8 SEGS M (w_sp w + 8) w2 ->
    0 <= w1 < 2 ^ 64 -> 0 <= w2 < 2 ^ 64 -> 0 <= w3 < 2 ^ 64 -> w1 mod 2 ^ 32 < 4 -> w3 mod 2 ^ 32 < 16 ->
    loop_mem w M -> cell4 SEGS M (w_sp w + 260) key ->
    (forall (fx' : FPState) A' R' M' model' (m2' : Z * Z * list (Z * (Z * (Z * Z * Z)))),
        frm_zero (@fp_csr fx') -> fconsts fx' -> PMX w A' M' model' (set_m2 c m2') -> pm_bud (w_n w) (set_m2 c m2') ->
        PmLoopU1.nodes (set_m2 c m2') + 1 <= c_widx c + 3 -> PmLoopU1.macct (set_m2 c m2') -> 2 * Zlen (t3c m2') <= c_widx c ->
        nt_kept_u1 R R' -> CRep.agree_on (fun a => w_sp w + 8 <= a < w_sp0 w) M M' ->
        srealizes SEGS (cfg fx' R' (hc_nt_exit HConstsU1.hc) M' model') K) ->
    srealizes SEGS (cfg fx R (hc_nt_entry HConstsU1.hc) M model) K.
